#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Convert markdown to HTML using a regex pattern
    std::regex htmlPattern(R"(
        <h[1-6]>(.*?)</h[1-6]>
        <p>(.*?)</p>
        <li>(.*?)</li>
        <ul>(.*?)</ul>
        <ol>(.*?)</ol>
        <blockquote>(.*?)</blockquote>
        <code>(.*?)</code>
        <a>(.*?)</a>
        <em>(.*?)</em>
        <strong>(.*?)</strong>
        <i>(.*?)</i>
        <u>(.*?)</u>
        <small>(.*?)</small>
        <div>(.*?)</div>
    )");

    std::string html;
    std::regex_replace(markdown, html, htmlPattern);

    return html;
}
```

